import{_ as e,o as d,c as r,a3 as o}from"./chunks/framework.DVCfY5-a.js";const p=JSON.parse('{"title":"API configuration","description":"","frontmatter":{"docLocale":"en","counterpart":"/reference/config","contentType":"reference","prev":false,"next":false},"headers":[],"relativePath":"en/reference/config.md","filePath":"en/reference/config.md"}'),n={name:"en/reference/config.md"};function a(c,t,i,s,l,_){return d(),r("div",null,[...t[0]||(t[0]=[o('<h1 id="api-configuration" tabindex="-1">API configuration <a class="header-anchor" href="#api-configuration" aria-label="Permalink to &quot;API configuration&quot;">​</a></h1><p>Node settings come directly from the running parser. See the <a href="./../guides/server-platform">platform guide</a> for usage. Production secrets never enter the documentation.</p><h2 id="current-lab-world-server" tabindex="-1">Current Lab World Server <a class="header-anchor" href="#current-lab-world-server" aria-label="Permalink to &quot;Current Lab World Server&quot;">​</a></h2><p>Defaults come from the running parser in <a href="https://github.com/CaiZongyuan/labworld/blob/bb30302126c39bfac561ae63dc395c2bf2195b1b/apps/server/src/config.ts" target="_blank" rel="noreferrer">config.ts</a>. The development entrypoint and Vite read <code>WEB_PORT</code> and <code>VITE_API_PROXY</code>.</p><table tabindex="0"><thead><tr><th>Variable</th><th>Default</th><th>Secret</th><th>Description</th></tr></thead><tbody><tr><td><code>LAB_WORD_NEWTON_SESSION</code></td><td>false</td><td>no</td><td>Enable fixed Newton Sessions; local management additionally requires pinned Python and scene inputs on Linux/WSL.</td></tr><tr><td><code>LAB_WORD_NEWTON_PYTHON</code></td><td></td><td>no</td><td>Pinned Python interpreter used only by explicit Newton Start.</td></tr><tr><td><code>LAB_WORD_NEWTON_SCENE_DIRECTORY</code></td><td></td><td>no</td><td>Prepared fixed scene directory containing the verified base GLB.</td></tr><tr><td><code>LAB_WORD_NEWTON_PUBLISHER</code></td><td></td><td>no</td><td>Optional absolute Newton publisher path; default is the bundled source.</td></tr><tr><td><code>LAB_WORD_TLS_CERT</code></td><td></td><td>no</td><td>Optional PEM certificate chain for the single HTTPS/WSS listener; requires TLS key and HTTPS APP_ORIGIN.</td></tr><tr><td><code>LAB_WORD_TLS_KEY</code></td><td></td><td>no</td><td>Optional PEM private key path paired with LAB_WORD_TLS_CERT; keep the file private.</td></tr><tr><td><code>LAB_WORD_SYNTHETIC_MANAGED</code></td><td>false</td><td>no</td><td>Own a local Synthetic child; empty inherits the Synthetic Session flag. Set false for an external machine source.</td></tr><tr><td><code>LAB_WORD_SYNTHETIC_SESSION</code></td><td>false</td><td>no</td><td>Enable Synthetic Sessions with reliable Recording; requires loopback plaintext or configured TLS.</td></tr><tr><td><code>LAB_WORD_SYNTHETIC_PYTHON</code></td><td>python3</td><td>no</td><td>Python executable used only for an explicit development synthetic Start.</td></tr><tr><td><code>LAB_WORD_SYNTHETIC_PUBLISHER</code></td><td></td><td>no</td><td>Optional absolute publisher.py path; default is the bundled development source.</td></tr><tr><td><code>LAB_WORD_MOTION_GRACE_MS</code></td><td>5000</td><td>no</td><td>Publisher heartbeat/source progress grace in milliseconds, 1000–60000.</td></tr><tr><td><code>LAB_WORD_MOTION_ACK_MS</code></td><td>3000</td><td>no</td><td>Correlated source lifecycle ACK deadline in milliseconds, 1000–60000.</td></tr><tr><td><code>LAB_WORD_MOTION_FIXTURE</code></td><td>false</td><td>no</td><td>Enable the authenticated synthetic motion fixture; requires a loopback bind.</td></tr><tr><td><code>LAB_WORD_WEB_DIR</code></td><td></td><td>no</td><td>Built Web directory for production same-origin hosting; empty disables static hosting.</td></tr><tr><td><code>LAB_WORD_HOST</code></td><td>127.0.0.1</td><td>no</td><td>Bind hostname. APP_BIND is the compatibility fallback.</td></tr><tr><td><code>SERVER_PORT</code></td><td>3000</td><td>no</td><td>Listen port, integer 1–65535.</td></tr><tr><td><code>APP_ORIGIN</code></td><td><a href="http://127.0.0.1:5173" target="_blank" rel="noreferrer">http://127.0.0.1:5173</a></td><td>no</td><td>Trusted Web origin; HTTPS or loopback HTTP.</td></tr><tr><td><code>SESSION_ABSOLUTE_SECS</code></td><td>604800</td><td>no</td><td>Absolute session seconds, 60–2592000.</td></tr><tr><td><code>SESSION_IDLE_SECS</code></td><td>86400</td><td>no</td><td>Idle session seconds, 60 through absolute lifetime.</td></tr><tr><td><code>RATE_LIMIT_ENABLED</code></td><td>true</td><td>no</td><td>Enable local limits; true or false.</td></tr><tr><td><code>RATE_LIMIT_WINDOW_SECS</code></td><td>60</td><td>no</td><td>Integer 1–3600; quotas use TCP peer and fallback cannot exceed primary.</td></tr><tr><td><code>RATE_LIMIT_MAX_LOCAL_ENTRIES</code></td><td>4096</td><td>no</td><td>Integer 1–100000; quotas use TCP peer and fallback cannot exceed primary.</td></tr><tr><td><code>RATE_LIMIT_REGISTRATION</code></td><td>20</td><td>no</td><td>Integer 1–1000000; quotas use TCP peer and fallback cannot exceed primary.</td></tr><tr><td><code>RATE_LIMIT_REGISTRATION_FALLBACK</code></td><td>5</td><td>no</td><td>Integer 1–1000000; quotas use TCP peer and fallback cannot exceed primary.</td></tr><tr><td><code>RATE_LIMIT_AUTHENTICATION</code></td><td>60</td><td>no</td><td>Integer 1–1000000; quotas use TCP peer and fallback cannot exceed primary.</td></tr><tr><td><code>RATE_LIMIT_AUTHENTICATION_FALLBACK</code></td><td>20</td><td>no</td><td>Integer 1–1000000; quotas use TCP peer and fallback cannot exceed primary.</td></tr><tr><td><code>RATE_LIMIT_RESOURCE</code></td><td>600</td><td>no</td><td>Integer 1–1000000; quotas use TCP peer and fallback cannot exceed primary.</td></tr><tr><td><code>RATE_LIMIT_RESOURCE_FALLBACK</code></td><td>120</td><td>no</td><td>Integer 1–1000000; quotas use TCP peer and fallback cannot exceed primary.</td></tr><tr><td><code>FILE_MAX_BYTES</code></td><td>20971520</td><td>no</td><td>Integer 1–104857600; streamed byte limit.</td></tr><tr><td><code>UPLOAD_SESSION_SECS</code></td><td>900</td><td>no</td><td>Integer 1–3600; capability lifetime in seconds.</td></tr><tr><td><code>DOWNLOAD_URL_SECS</code></td><td>60</td><td>no</td><td>Integer 1–300; capability lifetime in seconds.</td></tr><tr><td><code>FILE_PUBLIC_ORIGIN</code></td><td><a href="http://127.0.0.1:5173" target="_blank" rel="noreferrer">http://127.0.0.1:5173</a></td><td>no</td><td>Byte URL origin; defaults to trusted Web origin. HTTPS or loopback HTTP.</td></tr><tr><td><code>LAB_OBSERVATION_RETENTION_SECS</code></td><td>86400</td><td>no</td><td>Raw observation retention seconds (1–31536000). Current properties remain.</td></tr><tr><td><code>LAB_RECORD_RETENTION_SECS</code></td><td>2592000</td><td>no</td><td>Ended record retention seconds (1–31536000). Active Tasks remain.</td></tr><tr><td><code>LAB_WORD_DATA_DIR</code></td><td>data</td><td>no</td><td>Owned persistent DB, blobs and secrets directory. CONTRACT_DATA_DIRECTORY is the test fallback.</td></tr></tbody></table><p><a href="https://github.com/CaiZongyuan/labworld/blob/bb30302126c39bfac561ae63dc395c2bf2195b1b/.env.example" target="_blank" rel="noreferrer">.env.example</a> lists current Node and Web settings. The ordinary service does not use legacy database, Redis or object-storage configuration. See <a href="./../guides/server-foundation">TypeScript service foundation</a> to start the server and Web.</p>',6)])])}const u=e(n,[["render",a]]);export{p as __pageData,u as default};
